import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';

function AnomalyDetail() {
    const { id } = useParams();
    const navigate = useNavigate();
    const [anomaly, setAnomaly] = useState(null);
    const [loading, setLoading] = useState(true);
    const [closureNotes, setClosureNotes] = useState('');

    useEffect(() => {
        fetch(`http://localhost:8000/api/anomalies/${id}/`)
            .then(res => res.json())
            .then(data => {
                setAnomaly(data);
                setLoading(false);
            })
            .catch(err => {
                console.error('Error:', err);
                setLoading(false);
            });
    }, [id]);

    const getStatusColor = (status) => {
        const colors = {
            'new': '#e3f2fd',
            'approved': '#fff3e0',
            'assigned': '#fce4ec',
            'in_progress': '#f3e5f5',
            'resolved': '#e8f5e9',
            'closed': '#c8e6c9'
        };
        return colors[status] || '#f5f5f5';
    };

    if (loading) return <p>⏳ در حال بارگذاری...</p>;
    if (!anomaly) return <p>❌ آنومالی یافت نشد!</p>;

    return (
        <div style={{ maxWidth: '900px', margin: '0 auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                <h1>📋 {anomaly.anomaly_number}</h1>
                <button
                    onClick={() => navigate('/anomalies')}
                    style={{
                        padding: '8px 16px',
                        backgroundColor: '#666',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                    }}
                >
                    ← بازگشت
                </button>
            </div>

            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '8px', marginBottom: '20px' }}>
                <h2>{anomaly.title}</h2>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginTop: '15px' }}>
                    <div><strong>شماره:</strong> {anomaly.anomaly_number}</div>
                    <div><strong>وضعیت:</strong> <span style={{ backgroundColor: getStatusColor(anomaly.status), padding: '4px 12px', borderRadius: '12px' }}>{anomaly.status}</span></div>
                    <div><strong>مکان:</strong> {anomaly.location}</div>
                    <div><strong>سطح ریسک:</strong> {anomaly.risk_level}</div>
                    <div><strong>ثبت‌کننده:</strong> {anomaly.reported_by}</div>
                    <div><strong>تاریخ ثبت:</strong> {anomaly.reported_at}</div>
                    {anomaly.assigned_to && <div><strong>تخصیص به:</strong> {anomaly.assigned_to}</div>}
                    {anomaly.closed_at && <div><strong>تاریخ بسته شدن:</strong> {anomaly.closed_at}</div>}
                </div>
                <div style={{ marginTop: '15px' }}>
                    <strong>توضیحات:</strong>
                    <p>{anomaly.description}</p>
                </div>
                {anomaly.attachment && (
                    <div style={{ marginTop: '15px' }}>
                        <strong>📷 عکس پیوست:</strong>
                        <br />
                        <img src={`http://localhost:8000${anomaly.attachment}`} alt="Anomaly" style={{ maxWidth: '100%', maxHeight: '300px', marginTop: '10px' }} />
                    </div>
                )}
                {anomaly.closure_notes && (
                    <div style={{ marginTop: '15px', backgroundColor: '#e8f5e9', padding: '15px', borderRadius: '8px' }}>
                        <strong>📝 یادداشت بسته شدن:</strong>
                        <p>{anomaly.closure_notes}</p>
                    </div>
                )}
            </div>

            {/* گردش کار */}
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '8px' }}>
                <h3>⏳ گردش کار</h3>
                <div style={{ position: 'relative', padding: '10px 0' }}>
                    {anomaly.timeline && anomaly.timeline.map((item, index) => (
                        <div key={index} style={{ display: 'flex', alignItems: 'center', marginBottom: '10px' }}>
                            <div style={{ 
                                width: '40px', 
                                height: '40px', 
                                borderRadius: '50%', 
                                backgroundColor: '#1976d2', 
                                color: 'white',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                fontSize: '20px',
                                marginLeft: '15px'
                            }}>
                                {item.icon}
                            </div>
                            <div>
                                <div style={{ fontWeight: 'bold' }}>{item.status}</div>
                                <div style={{ fontSize: '14px', color: '#666' }}>
                                    {item.user} - {item.time}
                                </div>
                            </div>
                        </div>
                    ))}
                    {anomaly.status === 'closed' && (
                        <div style={{ marginTop: '15px', padding: '15px', backgroundColor: '#e8f5e9', borderRadius: '8px' }}>
                            <strong>✅ این آنومالی بسته شده است.</strong>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

export default AnomalyDetail;
